package tr.gov.kocaeli.sehir.location.api;
import tr.gov.kocaeli.sehir.location.domain.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/locations")public class LocationController{private final DistrictRepository districts;private final NeighborhoodRepository neighborhoods;public LocationController(DistrictRepository d,NeighborhoodRepository n){districts=d;neighborhoods=n;}@GetMapping("/districts")List<Item>districts(){return districts.findAllByOrderByName().stream().map(x->new Item(x.getId(),x.getCode(),x.getName())).toList();}@GetMapping("/districts/{id}/neighborhoods")List<Item>neighborhoods(@PathVariable UUID id){return neighborhoods.findByDistrictIdOrderByName(id).stream().map(x->new Item(x.getId(),x.getCode(),x.getName())).toList();}public record Item(UUID id,String code,String name){}}
